//! The gather and scatter tables.
//!
//! Generated by `scripts/vsib_tables.py` from what two
//! disassemblers say about every encoding of the family. The
//! opcodes are the only ones whose memory operand is addressed
//! by a vector register, and the width of that register is not
//! the width of the data register, so the rows record both.

use super::vector::Form;

/// One gather or scatter opcode.
pub struct VsibOp {
    /// The opcode byte.
    pub op: u8,
    /// The mandatory prefix.
    pub pp: u8,
    /// The mnemonic for the `W` bit clear.
    pub name: &'static str,
    /// The mnemonic for the `W` bit set.
    pub name_w: &'static str,
    /// The operand shape.
    pub form: Form,
    /// The width of one element of the memory operand, in bytes,
    /// when the `W` bit is clear.
    pub elem: u8,
    /// The same, when the `W` bit is set.
    pub elem_w: u8,
    /// The width of one element of the index register, in bytes.
    pub index: u8,
}

const VEX_VSIB: &[VsibOp] = &[
    vsib(0x90, 1, "vpgatherdd", "vpgatherdq", Form::Gather, 4, 8, 4),
    vsib(0x91, 1, "vpgatherqd", "vpgatherqq", Form::Gather, 4, 8, 8),
    vsib(0x92, 1, "vgatherdps", "vgatherdpd", Form::Gather, 4, 8, 4),
    vsib(0x93, 1, "vgatherqps", "vgatherqpd", Form::Gather, 4, 8, 8),
];

const EVEX_VSIB: &[VsibOp] = &[
    vsib(0x90, 1, "vpgatherdd", "vpgatherdq", Form::Two, 4, 8, 4),
    vsib(0x91, 1, "vpgatherqd", "vpgatherqq", Form::Two, 4, 8, 8),
    vsib(0x92, 1, "vgatherdps", "vgatherdpd", Form::Two, 4, 8, 4),
    vsib(0x93, 1, "vgatherqps", "vgatherqpd", Form::Two, 4, 8, 8),
    vsib(
        0xa0,
        1,
        "vpscatterdd",
        "vpscatterdq",
        Form::Scatter,
        4,
        8,
        4,
    ),
    vsib(
        0xa1,
        1,
        "vpscatterqd",
        "vpscatterqq",
        Form::Scatter,
        4,
        8,
        8,
    ),
    vsib(
        0xa2,
        1,
        "vscatterdps",
        "vscatterdpd",
        Form::Scatter,
        4,
        8,
        4,
    ),
    vsib(
        0xa3,
        1,
        "vscatterqps",
        "vscatterqpd",
        Form::Scatter,
        4,
        8,
        8,
    ),
];

/// `const` constructor, so the table stays readable.
#[allow(clippy::too_many_arguments)]
const fn vsib(
    op: u8,
    pp: u8,
    name: &'static str,
    name_w: &'static str,
    form: Form,
    elem: u8,
    elem_w: u8,
    index: u8,
) -> VsibOp {
    VsibOp {
        op,
        pp,
        name,
        name_w,
        form,
        elem,
        elem_w,
        index,
    }
}

/// The row for one opcode, in the encoding the caller is reading.
pub fn lookup(evex: bool, op: u8, pp: u8) -> Option<&'static VsibOp> {
    let table = if evex { EVEX_VSIB } else { VEX_VSIB };
    table.iter().find(|e| e.op == op && e.pp == pp)
}
